    __u32 key = 0;
    __u64 *value = bpf_map_lookup_elem(&my_map, &key);

    /* 错误: 未检查 NULL */
    *value += 1;  /* 验证器拒绝: value 可能为 NULL */

    return XDP_PASS;
}

/* 修复: 必须检查 NULL */
SEC("xdp")
int good_null_check(struct xdp_md *ctx) {
    __u32 key = 0;
    __u64 *value = bpf_map_lookup_elem(&my_map, &key);

    /* 正确: 检查 NULL 后再访问 */
    if (!value)
        return XDP_PASS;

    *value += 1;  /* 安全: 已验证非 NULL */

    return XDP_PASS;
}

