/* TC eBPF 程序示例 - 服务负载均衡 */
#include <linux/bpf.h>
#include <linux/pkt_cls.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

/* 后端服务器 Map */
struct backend {
    __u32 ip;
    __u16 port;
    __u8  weight;
    __u8  active;
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 8);
    __type(key, __u32);
    __type(value, struct backend);
} backends SEC(".maps");

/* 连接跟踪 Map */
struct conn_key {
    __u32 src_ip;
    __u16 src_port;
    __u32 dst_ip;
    __u16 dst_port;
};

struct conn_val {
    __u32 backend_ip;
    __u16 backend_port;
    __u64 last_seen;
};

struct {
    __uint(type, BPF_MAP_TYPE_LRU_HASH);
    __uint(max_entries, 65536);
    __type(key, struct conn_key);
    __type(value, struct conn_val);
} conn_track SEC(".maps");

static __always_inline __u16 csum_fold(__u32 csum) {
    csum = (csum & 0xffff) + (csum >> 16);
    csum = (csum & 0xffff) + (csum >> 16);
    return (__u16)~csum;
}

SEC("tc")
int tc_load_balancer(struct __sk_buff *skb) {
    void *data_end = (void *)(long)skb->data_end;
    void *data = (void *)(long)skb->data;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return TC_ACT_SHOT;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return TC_ACT_OK;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return TC_ACT_SHOT;

    if (ip->protocol != IPPROTO_TCP)
        return TC_ACT_OK;

    __u32 ip_hdr_len = ip->ihl * 4;
    struct tcphdr *tcp = (void *)ip + ip_hdr_len;
    if ((void *)(tcp + 1) > data_end)
        return TC_ACT_SHOT;

    /* 检查是否是到 VIP 的流量 */
    __u32 vip = bpf_htonl(0xC0A80001);  /* 192.168.0.1 */
    if (ip->daddr != vip)
        return TC_ACT_OK;

    /* 查找已有连接 */
    struct conn_key ckey = {
        .src_ip = ip->saddr,
        .src_port = tcp->source,
        .dst_ip = ip->daddr,
        .dst_port = tcp->dest,
    };

    struct conn_val *cval = bpf_map_lookup_elem(&conn_track, &ckey);

    __u32 backend_ip;
    __u16 backend_port;

    if (cval) {
        /* 使用已有连接的后端 */
        backend_ip = cval->backend_ip;
        backend_port = cval->backend_port;
    } else {
        /* 选择后端 (简单轮询) */
        __u32 idx = bpf_get_prandom_u32() % 3;
        struct backend *be = bpf_map_lookup_elem(&backends, &idx);
        if (!be || !be->active)
            return TC_ACT_SHOT;

        backend_ip = be->ip;
        backend_port = be->port;

        /* 记录连接 */
        struct conn_val new_val = {
            .backend_ip = backend_ip,
            .backend_port = backend_port,
            .last_seen = bpf_ktime_get_ns(),
        };
        bpf_map_update_elem(&conn_track, &ckey, &new_val, BPF_ANY);
    }

    /* 修改目标 IP 和端口 (DNAT) */
    /* 注意: 实际需要更新校验和 */
    bpf_skb_store_bytes(skb, 
        (void *)&ip->daddr - data,
        &backend_ip, 4, BPF_F_RECOMPUTE_CSUM);
    bpf_skb_store_bytes(skb,
        (void *)&tcp->dest - data,
        &backend_port, 2, BPF_F_RECOMPUTE_CSUM);

    return TC_ACT_OK;
}

