/* kprobe 跟踪内核函数示例 */
#include <linux/bpf.h>
#include <linux/ptrace.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_tracing.h>
#include <bpf/bpf_core_read.h>

/* 文件打开事件结构 */
struct file_open_event {
    __u64 timestamp;
    __u32 pid;
    __u32 uid;
    char comm[16];
    char filename[256];
    int flags;
    int ret;  /* 仅 kretprobe 有效 */
};

/* Ring Buffer 传递事件 */
struct {
    __uint(type, BPF_MAP_TYPE_RINGBUF);
    __uint(max_entries, 1 << 24);  /* 16 MB */
} events SEC(".maps");

/* kprobe: 在 do_sys_openat2 入口处执行 */
SEC("kprobe/do_sys_openat2")
int BPF_KPROBE(kprobe_openat2, int dfd, const char __user *filename, 
               struct open_how *how) {
    struct file_open_event *event;

    /* 分配 ring buffer 空间 */
    event = bpf_ringbuf_reserve(&events, sizeof(*event), 0);
    if (!event)
        return 0;

    event->timestamp = bpf_ktime_get_ns();
    event->pid = bpf_get_current_pid_tgid() >> 32;
    event->uid = bpf_get_current_uid_gid() & 0xFFFFFFFF;
    bpf_get_current_comm(event->comm, sizeof(event->comm));

    /* 安全读取用户态字符串 */
    bpf_probe_read_user_str(event->filename, sizeof(event->filename), filename);

    /* 读取 open_how 结构体的 flags 字段 (使用 CO-RE) */
    event->flags = BPF_CORE_READ(how, flags);
    event->ret = 0;

    /* 提交事件 */
    bpf_ringbuf_submit(event, 0);

    return 0;
}

/* kretprobe: 在 do_sys_openat2 返回时执行 */
SEC("kretprobe/do_sys_openat2")
int BPF_KRETPROBE(kretprobe_openat2, long ret) {
    /* 仅关注失败的 open 调用 */
    if (ret >= 0)
        return 0;

    struct file_open_event *event;
    event = bpf_ringbuf_reserve(&events, sizeof(*event), 0);
    if (!event)
        return 0;

    event->timestamp = bpf_ktime_get_ns();
    event->pid = bpf_get_current_pid_tgid() >> 32;
    event->uid = bpf_get_current_uid_gid() & 0xFFFFFFFF;
    bpf_get_current_comm(event->comm, sizeof(event->comm));
    event->ret = ret;

    bpf_ringbuf_submit(event, 0);
    return 0;
}

